import React from 'react';
import { render, screen } from '@testing-library/react';
import { EmptyState } from '../..';

describe('EmptyState', () => {
  test('should render empty page level without crashing', () => {
    render(
      <EmptyState.PageLevel
        data-testid="pagelevel-component"
        title="Imagine a title"
        description="Imagine a description"
        ilustrationName="beesCategory"
        actions={[
          { name: 'Action', variant: 'secondary', action: () => console.log('working1') },
          { name: 'Action2', variant: 'primary', action: () => console.log('working2') },
        ]}
      />
    );
    expect(screen.getByText('Imagine a title')).toBeInTheDocument();
    expect(screen.getByText('Imagine a description')).toBeInTheDocument();
    expect(screen.getByText('Action')).toBeInTheDocument();
    expect(screen.getByText('Action2')).toBeInTheDocument();
    expect(screen.getByTestId('pagelevel-component')).toBeInTheDocument();
  });
  test('should render empty page level with custom image', () => {
    render(
      <EmptyState.PageLevel
        data-testid="pagelevel-component"
        title="Imagine a title"
        description="Imagine a description"
        customIlustration={{
          src: 'https://cms-non-prod.global.ssl.fastly.net/media/09-24-2021-ccf86e27-7fca-4f42-ae5d-a2d2bc86e906-c2ef551a.png',
          alt: 'coronaExtra',
          width: '246px',
          height: '246px',
        }}
      />
    );
    expect(screen.getByText('Imagine a title')).toBeInTheDocument();
    expect(screen.getByText('Imagine a description')).toBeInTheDocument();
    expect(screen.getByTestId('pagelevel-component')).toBeInTheDocument();
  });

  test('should render empty section level without crashing', () => {
    render(
      <EmptyState.SectionLevel
        data-testid="sectionlevel-component"
        description="Imagine a description"
        ilustrationName="beesCategory"
      />
    );
    expect(screen.getByTestId('sectionlevel-component')).toBeInTheDocument();
    expect(screen.getByText('Imagine a description')).toBeInTheDocument();
  });
  test('should render empty section level with custom image', () => {
    render(
      <EmptyState.SectionLevel
        data-testid="sectionlevel-component"
        description="Imagine a description"
        customIlustration={{
          src: 'https://cms-non-prod.global.ssl.fastly.net/media/09-24-2021-ccf86e27-7fca-4f42-ae5d-a2d2bc86e906-c2ef551a.png',
          alt: 'coronaExtra',
          width: '246px',
          height: '246px',
        }}
      />
    );
    expect(screen.getByTestId('sectionlevel-component')).toBeInTheDocument();
    expect(screen.getByText('Imagine a description')).toBeInTheDocument();
  });
});
